declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Formula;

use DateTimeImmutable;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKey;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\UserPersonalApiKeyCreatedAtVO;

class CreatedAtCalculator
{
    public static function calculateCreatedAt(?UserPersonalApiKey $original = null): UserPersonalApiKeyCreatedAtVO
    {
        return $original ? $original->createdAt() : UserPersonalApiKeyCreatedAtVO::from(new DateTimeImmutable('now'));
    }
}
